using System;using System.Threading;
class QuestCleanupTest {
 static void CleanupCancellation(){var c=new CancellationTokenSource();int cleaned=0;bool cancelled=false;try{QuestDelivery.Execute(()=>false,()=>{c.Cancel();throw new OperationCanceledException();},()=>true,()=>{},()=>false,()=>cleaned++,c.Token);}catch(OperationCanceledException){cancelled=true;}Assert(cancelled&&cleaned==1,"cancelamento depois de abrir NPC ainda encerra interacao");} static void ErrorPolicy(){int opens=0;bool present=false;var outcome=QuestDelivery.Execute(()=>present,()=>{if(++opens==1)throw new Exception("temporaria");},()=>true,()=>present=true,()=>present,()=>{},CancellationToken.None,()=>true);Assert(outcome.Confirmed&&opens==2,"erro temporario permite nova tentativa no personagem afetado");opens=0;bool stopped=false;try{QuestDelivery.Execute(()=>false,()=>{opens++;throw new Exception("ponte nao restaurada");},()=>true,()=>{},()=>false,()=>{},CancellationToken.None,()=>false);}catch(Exception){stopped=true;}Assert(stopped&&opens==1,"ponte sem restauracao bloqueia novos comandos");}
 sealed class Fake {public int Opens,Accepts,Closed,Required=1;public bool Present,CloseFails;public QuestDelivery.Outcome Run(){return QuestDelivery.Execute(()=>Present,()=>Opens++,()=>true,()=>Accepts++,()=>{if(Accepts>=Required)Present=true;return Present;},()=>{Closed++;if(CloseFails)throw new Exception("fechamento simulado");},CancellationToken.None);}}
 static void Assert(bool test,string text){if(!test)throw new Exception(text);Console.WriteLine("PASS "+text);}
 static int Main(){try{CleanupCancellation();ErrorPolicy();var a=new Fake();var b=new Fake{Required=3};var first=a.Run();var second=b.Run();Assert(first.Confirmed&&second.Confirmed&&a.Accepts==1&&b.Accepts==3,"somente o personagem que falhou recebe novas tentativas");Assert(a.Closed==1&&b.Closed==1,"janelas fechadas uma vez apos confirmar recebimento");var existing=new Fake{Present=true};var already=existing.Run();Assert(already.Confirmed&&already.AlreadyPresent&&existing.Accepts==0&&existing.Closed==0,"missao existente nao e repetida nem fecha uma janela alheia");var failure=new Fake{Required=99};var failed=failure.Run();Assert(!failed.Confirmed&&failure.Accepts==3&&failure.Closed==1,"tres falhas limitam tentativas e nao indicam sucesso");var closing=new Fake{CloseFails=true};var accepted=closing.Run();Assert(accepted.Confirmed&&closing.Accepts==1&&accepted.CloseError!=null,"falha ao fechar janela nao repete missao recebida");var cancel=new CancellationTokenSource();cancel.Cancel();bool stopped=false;try{QuestDelivery.Execute(()=>false,()=>{throw new Exception("nao deve executar");},()=>true,()=>{},()=>true,()=>{},cancel.Token);}catch(OperationCanceledException){stopped=true;}Assert(stopped,"cancelamento impede novos comandos");return 0;}catch(Exception e){Console.WriteLine(e);return 1;}}
}
